1	<!DOCTYPE html>
2	<html lang="pt-BR">
3	<head>
4	<meta charset="UTF-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Escritório Virtual cuidar.vc</title>
7	<style>
8	:root{--woodtop:#dcb284;--woodside:#a97e4f;--wooddark:#8a6239;--wallc:#d7dcd2;--wall2:#b3bfae;--ink:#26221c;--accent:#0d9488;--neon:#8de9d8;--ease:cubic-bezier(.16,1,.3,1);--tilt:56deg}
9	*{margin:0;padding:0;box-sizing:border-box}
10	body{font-family:system-ui,-apple-system,'Segoe UI',sans-serif;background:radial-gradient(1200px 600px at 50% -100px,#122028,#0a0f12 70%);color:#f5f1e8;min-height:100vh}
11	header{display:flex;flex-wrap:wrap;gap:8px;align-items:center;justify-content:space-between;padding:10px 14px;background:#0d1518e6;border-bottom:2px solid var(--accent);position:sticky;top:0;z-index:50;backdrop-filter:blur(6px)}
12	header h1{font-size:16px}
13	.hinfo{display:flex;gap:8px;align-items:center;flex-wrap:wrap;font-size:12px}
14	.badge{background:#123f38;border:1px solid var(--accent);color:var(--neon);border-radius:20px;padding:4px 10px;font-weight:600}
15	.badge.warn{background:#4a1512;border-color:#e05d4b;color:#ffb3a6}
16	#clock{font-variant-numeric:tabular-nums;background:#1a2422;border-radius:8px;padding:4px 8px}
17	.wrap{max-width:1180px;margin:0 auto;padding:12px 10px 0}
18	.chips{display:flex;gap:6px;overflow-x:auto;padding:2px 2px 8px;scrollbar-width:none}
19	.chips::-webkit-scrollbar{display:none}
20	.chips span{background:#131b1e;border:1px solid #24343a;color:#d8e2dd;border-radius:14px;padding:4px 10px;font-size:12px;white-space:nowrap}
21	.fitwrap{position:relative;margin:0 auto;overflow:hidden;border-radius:16px}
22	.fitwrap.zoomed{overflow-x:auto;cursor:grab}
23	.scenebox{transform-origin:0 0}
24	.viewport{position:relative;width:1140px;height:640px;perspective:1500px;perspective-origin:50% 20%;background:linear-gradient(180deg,#1d2f36 0%,#101a1e 100%);border-radius:16px;box-shadow:0 24px 60px rgba(0,0,0,.55),0 0 0 1px #21343a;overflow:hidden}
25	.viewport::after{content:'';position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 30%,transparent 55%,rgba(4,8,10,.5));z-index:99}
26	.world{position:relative;width:1140px;height:660px;transform-style:preserve-3d;transform:rotateX(var(--tilt)) translateZ(0)}
27	.floor{position:absolute;inset:0;border-radius:12px;background:linear-gradient(180deg,#d8b588,#c89b6d 70%,#bd8f61);box-shadow:inset 0 0 0 3px #b3855a,inset 0 0 60px rgba(120,80,30,.35)}
28	.floor::before{content:'';position:absolute;inset:0;border-radius:12px;background:repeating-linear-gradient(90deg,transparent 0 112px,rgba(90,60,25,.18) 112px 114px),repeating-linear-gradient(0deg,transparent 0 190px,rgba(255,240,210,.09) 190px 192px)}
29	.wshade{position:absolute;inset:0;border-radius:12px;background:radial-gradient(ellipse at 50% 0%,rgba(255,255,240,.16),transparent 60%);pointer-events:none}
30	.rug{position:absolute;left:330px;top:300px;width:230px;height:150px;background:radial-gradient(#d9cbb4,#b3a288);border-radius:50%;box-shadow:0 4px 0 rgba(0,0,0,.15);opacity:.9}
31	.walln{position:absolute;left:0;top:0;width:1140px;height:128px;transform-origin:top;transform:rotateX(90deg);background:linear-gradient(180deg,var(--wallc),var(--wall2) 78%,#9aa794);box-shadow:inset 0 -6px 0 rgba(0,0,0,.12);backface-visibility:hidden}
32	.walle{position:absolute;right:0;top:0;width:280px;height:128px;transform-origin:right;transform:rotateY(-90deg);background:linear-gradient(180deg,#c4cec0,#a8b4a2 78%,#93a08c);backface-visibility:hidden}
33	.win{position:absolute;height:66px;top:30px;border-radius:8px;background:linear-gradient(#9fd4ec,#e6f6fb 70%,#cfeaf6);border:4px solid #7d766a;box-shadow:0 0 18px rgba(150,220,255,.5),inset 0 3px 8px rgba(255,255,255,.7);overflow:hidden}
34	.win::before{content:'';position:absolute;left:-80px;top:10px;width:56px;height:12px;background:#ffffffd9;border-radius:10px;box-shadow:34px 6px 0 -2px #ffffffb3,90px 2px 0 -4px #ffffff96;animation:clouds 36s linear infinite}
35	.win::after{content:'';position:absolute;right:22px;top:10px;width:14px;height:14px;border-radius:50%;background:radial-gradient(#ffe9a0,#f7c948);box-shadow:0 0 12px #ffd76e99;animation:sun 5s ease-in-out infinite}
36	@keyframes clouds{to{transform:translateX(820px)}}
37	@keyframes sun{50%{transform:scale(1.15)}}
38	.glassn{position:absolute;left:848px;top:0;width:292px;height:128px;transform-origin:top;transform:rotateX(90deg);background:linear-gradient(180deg,rgba(210,235,240,.55),rgba(190,220,230,.28));border-left:3px solid rgba(255,255,255,.55);backdrop-filter:blur(2px)}
39	.glasse{position:absolute;right:0;top:0;width:280px;height:128px;transform-origin:right;transform:rotateY(-90deg);background:linear-gradient(90deg,rgba(190,220,230,.4),rgba(210,235,240,.18));border-top:3px solid rgba(255,255,255,.45)}
40	.zlab{position:absolute;transform:translateZ(26px) rotateX(calc(-1*var(--tilt)));transform-origin:50% 100%;font-size:11px;font-weight:700;letter-spacing:.4px;color:#4b5d54;background:#f0ead9cc;border:1px solid #b8ae98;border-radius:12px;padding:3px 10px;white-space:nowrap;box-shadow:0 3px 8px rgba(0,0,0,.25)}
41	.shadow{position:absolute;border-radius:50%;background:rgba(20,12,4,.35);filter:blur(3px)}
42	.box{position:absolute;transform-style:preserve-3d}
43	.box>div{position:absolute;backface-visibility:hidden}
44	.btop{inset:0;background:var(--woodtop);border:2px solid #b3855a;border-radius:8px;box-shadow:inset 0 2px 0 #f1d3a9}
45	.bsn{left:0;top:100%;width:100%;height:var(--h);transform-origin:top;transform:rotateX(-90deg);background:linear-gradient(180deg,var(--woodside),var(--wooddark))}
46	.bss{left:0;top:calc(-1*var(--h));width:100%;height:var(--h);transform-origin:bottom;transform:rotateX(90deg);background:linear-gradient(0deg,var(--woodside),var(--wooddark))}
47	.bse{left:calc(-1*var(--h));top:0;width:var(--h);height:100%;transform-origin:right;transform:rotateY(-90deg);background:var(--wooddark)}
48	.bsw{right:calc(-1*var(--h));top:0;width:var(--h);height:100%;transform-origin:left;transform:rotateY(90deg);background:var(--woodside)}
49	.box .btop{transform:translateZ(var(--h))}
50	.mon{position:absolute;left:12px;top:-40px;width:30px;height:24px;background:linear-gradient(#20313a,#101c22);border:2px solid #0b1418;border-radius:4px;box-shadow:0 0 10px rgba(141,233,216,.45);animation:mglow 2.6s ease-in-out infinite}
51	.mon::after{content:'';position:absolute;inset:3px;background:linear-gradient(135deg,#8de9d855,#5db6d955);border-radius:2px}
52	.mon::before{content:'';position:absolute;left:12px;top:24px;width:4px;height:10px;background:#0b1418}
53	@keyframes mglow{50%{box-shadow:0 0 16px rgba(141,233,216,.85)}}
54	.bb{position:absolute;transform-origin:50% 100%;transform:translateX(-50%) translateZ(var(--z,40px)) rotateX(calc(-1*var(--tilt)))}
55	.plate{position:relative;background:rgba(16,24,22,.92);color:#f5f1e8;border-radius:10px;padding:5px 9px;font-size:11px;line-height:1.35;text-align:center;white-space:nowrap;box-shadow:0 4px 10px rgba(0,0,0,.35);border:1px solid rgba(141,227,216,.4)}
56	.plate b{color:var(--neon);display:block;font-size:12px}
57	.plate .st{color:#ffe9a8;display:block;max-width:190px;overflow:hidden;text-overflow:ellipsis}
58	.lp{position:relative;width:70px;padding:4px 2px;font-size:10px;background:rgba(16,24,22,.92);color:#f5f1e8;border-radius:9px;text-align:center;white-space:nowrap;box-shadow:0 4px 10px rgba(0,0,0,.35);border:1px solid rgba(141,227,216,.4)}
59	.lp b{color:var(--neon);display:block;font-size:9.5px}
60	.lp .st{color:#ffe9a8;display:block;font-size:9px;max-width:64px;margin:0 auto;overflow:hidden;text-overflow:ellipsis}
61	.prop{position:relative;font-size:30px;filter:drop-shadow(0 4px 4px rgba(0,0,0,.35));user-select:none;line-height:1}
62	.prop small{display:block;font-size:9px;font-weight:600;background:#f0ead9e0;color:#4b4335;border-radius:6px;padding:1px 5px;margin-top:2px;text-align:center}
63	.agent{position:absolute;width:24px;height:46px;transform-style:preserve-3d;cursor:pointer;user-select:none;z-index:30;opacity:0;transition:opacity .7s var(--ease)}
64	.agent.in{opacity:1}
65	.agent .ashadow{position:absolute;left:-1px;bottom:-2px;width:26px;height:8px;background:rgba(20,12,4,.4);border-radius:50%;filter:blur(2px)}
66	.agent .bill{position:absolute;inset:0;transform-origin:50% 100%;transform:rotateX(calc(-1*var(--tilt)))}
67	.fig{position:absolute;left:0;bottom:0;width:24px;height:44px;transition:transform .16s ease}
68	.agent.flip .fig{transform:scaleX(-1)}
69	.bobw{position:absolute;inset:0}
70	.bobw>div{position:absolute}
71	.head{left:5px;top:0;width:14px;height:13px;background:var(--sk);border-radius:7px 7px 5px 5px;z-index:3}
72	.hair{position:absolute;left:-1px;top:-2px;width:16px;height:7px;background:var(--hc);border-radius:8px 8px 3px 3px}
73	.eye{position:absolute;top:5px;width:2.5px;height:2.5px;background:#26221c;border-radius:50%;animation:blink 4.6s infinite;animation-delay:var(--bd,0s)}
74	.eye.l{left:3px}.eye.r{right:3px}
75	@keyframes blink{0%,93%,100%{transform:scaleY(1)}95%{transform:scaleY(.08)}}
76	.torso{left:4px;top:13px;width:16px;height:15px;background:var(--c);border-radius:5px 5px 4px 4px;z-index:2}
77	.arm{top:14px;width:4px;height:13px;background:var(--c);border-radius:2px;transform-origin:2px 2px;z-index:1}
78	.arm.l{left:0}.arm.r{right:0}
79	.leg{top:27px;width:5px;height:14px;background:#3a3f4a;border-radius:2px;transform-origin:2.5px 0}
80	.leg.l{left:6px}.leg.r{right:6px}
81	.agent.walking .leg.l{animation:swing .34s ease-in-out infinite}
82	.agent.walking .leg.r{animation:swing .34s ease-in-out infinite reverse}
83	.agent.walking .arm.l{animation:swing .34s ease-in-out infinite reverse}
84	.agent.walking .arm.r{animation:swing .34s ease-in-out infinite}
85	@keyframes swing{0%,100%{transform:rotate(22deg)}50%{transform:rotate(-22deg)}}
86	.agent.walking .bobw{animation:bob .17s ease-in-out infinite alternate}
87	@keyframes bob{from{transform:translateY(0)}to{transform:translateY(-2px)}}
88	.agent.standing .bobw{animation:breathe 2.9s ease-in-out infinite}
89	@keyframes breathe{0%,100%{transform:translateY(0)}50%{transform:translateY(-1px)}}
90	.agent.typing .leg{transform:rotate(80deg) scaleY(.5);transform-origin:50% 0}
91	.agent.typing .arm{transform:rotate(52deg)}
92	.agent.typing .arm.l{animation:type .24s ease-in-out infinite alternate}
93	.agent.typing .arm.r{animation:type .24s .12s ease-in-out infinite alternate}
94	@keyframes type{from{transform:rotate(46deg)}to{transform:rotate(58deg)}}
95	.agent.typing .head{animation:tnod 4.5s ease-in-out infinite}
96	@keyframes tnod{0%,88%,100%{transform:translateY(0)}92%{transform:translateY(1px) rotate(3deg)}}
97	.agent .zzz{position:absolute;top:-12px;right:-8px;font:700 12px system-ui;color:#9fb4c9;opacity:0;pointer-events:none}
98	.agent.sleep .zzz{animation:zzz 2.6s ease-in-out infinite}
99	@keyframes zzz{0%{opacity:0;transform:translate(0,0) scale(.7)}30%{opacity:1}100%{opacity:0;transform:translate(12px,-24px) scale(1.25)}}
100	.tag{position:absolute;bottom:-15px;left:50%;transform:translateX(-50%);font-size:9px;font-weight:600;background:#26221cd9;color:var(--neon);border-radius:6px;padding:0 4px;white-space:nowrap}
101	.bub{position:absolute;bottom:48px;left:50%;transform:translateX(-50%) scale(.6);transform-origin:50% 100%;background:#fff;border:1px solid #cfc7b5;border-radius:10px;padding:3px 8px;font-size:11px;white-space:nowrap;box-shadow:0 4px 10px rgba(0,0,0,.2);opacity:0;transition:transform .3s cubic-bezier(.34,1.56,.64,1),opacity .22s;pointer-events:none;max-width:240px;overflow:hidden;text-overflow:ellipsis;z-index:5;color:var(--ink)}
102	.agent.say .bub,.agent:hover .bub{opacity:1;transform:translateX(-50%) scale(1)}
103	.bub::after{content:'';position:absolute;bottom:-5px;left:50%;margin-left:-5px;width:8px;height:8px;background:#fff;border-right:1px solid #cfc7b5;border-bottom:1px solid #cfc7b5;transform:rotate(45deg)}
104	.steam i{position:absolute;width:6px;height:6px;border-radius:50%;background:rgba(255,255,255,.8);filter:blur(2px);animation:rise 2.3s ease-out infinite}
105	.steam i:nth-child(2){left:9px;animation-delay:.75s}
106	.steam i:nth-child(3){left:-2px;animation-delay:1.4s}
107	@keyframes rise{0%{transform:translateY(6px) scale(.5);opacity:0}25%{opacity:.9}100%{transform:translateY(-24px) scale(1.5);opacity:0}}
108	#card{position:fixed;right:14px;bottom:14px;width:270px;background:linear-gradient(180deg,#152420,#0d1512);color:#f5f1e8;border:1px solid var(--accent);border-radius:12px;padding:14px;font-size:13px;box-shadow:0 10px 30px rgba(0,0,0,.5);display:none;z-index:200}
109	#card h3{color:var(--neon);margin-bottom:6px;font-size:15px}
110	#card .x{position:absolute;top:6px;right:10px;cursor:pointer;color:#888}
111	#card p{margin:3px 0;line-height:1.45}
112	#card b{color:#ffe9a8}
113	.foot{color:#7d8a85;font-size:11px;margin-top:8px;text-align:center;padding-bottom:8px}
114	.fitbtn{position:absolute;top:10px;right:12px;z-index:100;background:#0d151ecc;border:1px solid var(--accent);color:var(--neon);border-radius:10px;padding:5px 10px;font-size:12px;cursor:pointer;backdrop-filter:blur(4px)}
115	.dashsec{max-width:1180px;margin:8px auto 44px;padding:0 10px}
116	.dashtop{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px;margin-bottom:8px}
117	.dashtop h2{font-size:15px;color:#f5f1e8;font-weight:700}
118	.dashtop a{color:var(--neon);font-size:12px;text-decoration:none;border:1px solid var(--accent);border-radius:8px;padding:4px 10px;white-space:nowrap}
119	.dashsec iframe{width:100%;height:920px;border:0;border-radius:14px;background:#14120f;box-shadow:0 10px 30px rgba(0,0,0,.45);display:block}
120	@media(max-width:640px){.dashsec iframe{height:1250px}}
121	</style>
122	</head>
