import { spawn } from 'node:child_process';
import { writeFileSync } from 'node:fs';
const CHROME = '/home/hermes/.cache/ms-playwright/chromium-1234/chrome-linux64/chrome';
const url = process.argv[2];
const width = +process.argv[3] || 1280;
const out = process.argv[4] || '/tmp/v4test/shot.png';
const waitMs = +process.argv[5] || 6000;
const port = 9300 + Math.floor(Math.random() * 500);
const ch = spawn(CHROME, ['--headless=new', '--no-sandbox', '--disable-gpu', '--hide-scrollbars', `--remote-debugging-port=${port}`, `--window-size=${width},1000`, 'about:blank'], { stdio: 'ignore' });
const sleep = ms => new Promise(r => setTimeout(r, ms));
let ws;
for (let i = 0; i < 50; i++) { try { const r = await fetch(`http://127.0.0.1:${port}/json`); const j = await r.json(); const pg = j.find(t => t.type === 'page'); if (pg) { ws = new WebSocket(pg.webSocketDebuggerUrl); break; } } catch { } await sleep(200); }
await new Promise(r => ws.onopen = r);
let id = 0; const pend = {}; const errs = [];
ws.onmessage = ev => { const m = JSON.parse(ev.data); if (m.id && pend[m.id]) { pend[m.id](m); delete pend[m.id]; }
  if (m.method === 'Runtime.exceptionThrown') errs.push('EXC ' + JSON.stringify(m.params.exceptionDetails).slice(0, 500));
  if (m.method === 'Runtime.consoleAPICalled' && ['error', 'warning'].includes(m.params.type)) errs.push('CONSOLE ' + m.params.type + ' ' + JSON.stringify(m.params.args).slice(0, 300));
  if (m.method === 'Log.entryAdded') errs.push('LOG ' + m.params.entry.level + ' ' + m.params.entry.text + ' ' + (m.params.entry.url || ''));
};
const send = (method, params = {}) => new Promise(r => { const i = ++id; pend[i] = r; ws.send(JSON.stringify({ id: i, method, params })); });
await send('Runtime.enable'); await send('Log.enable'); await send('Page.enable');
await send('Emulation.setDeviceMetricsOverride', { width, height: 1000, deviceScaleFactor: 1, mobile: width < 500 });
await send('Page.navigate', { url });
await sleep(waitMs);
const expr = process.argv[6] || `(()=>{const vp=document.getElementById('vp').getBoundingClientRect();const ps=[...document.querySelectorAll('.plate')].map(p=>{const r=p.getBoundingClientRect();return {t:p.textContent,l:r.left,t2:r.top,r:r.right,b:r.bottom,sw:p.scrollWidth,cw:p.clientWidth}});const ov=[];for(let i=0;i<ps.length;i++)for(let j=i+1;j<ps.length;j++){const a=ps[i],b=ps[j];if(a.l<b.r&&b.l<a.r&&a.t2<b.b&&b.t2<a.b)ov.push(a.t+' X '+b.t)}const outside=ps.filter(p=>p.l<vp.left-0.5||p.r>vp.right+0.5||p.t2<vp.top-0.5||p.b>vp.bottom+0.5).map(p=>p.t);const clipped=ps.filter(p=>p.sw>p.cw+1).map(p=>p.t);const ag=[...document.querySelectorAll('.agent')].map(a=>a.className.split(' ').filter(c=>['walk','sit','idle'].includes(c)).join());return JSON.stringify({vp:[vp.left,vp.top,vp.width,vp.height],docW:document.documentElement.scrollWidth,plates:ps.length,overlaps:ov,outside,clipped,agents:ag,iframe:document.querySelector('iframe').getAttribute('src'),h2:document.querySelector('.dash h2').textContent})})()`;
const res = await send('Runtime.evaluate', { expression: expr, returnByValue: true });
console.log(res.result.result.value);
const shot = await send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: false });
writeFileSync(out, Buffer.from(shot.result.data, 'base64'));
console.log('ERRORS:', errs.length ? errs.join('\n') : 'none');
ws.close(); ch.kill();
process.exit(0);

